import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";

export interface AttackTechnique {
  id: string;
  technique_id: string;
  name: string;
  tactic: string;
  description: string | null;
  parent_id: string | null;
  platforms: string[];
  url: string | null;
}

export function useAttackTechniques() {
  return useQuery({
    queryKey: ["attack_techniques"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("attack_techniques")
        .select("*")
        .order("tactic")
        .order("technique_id");
      if (error) throw error;
      return (data ?? []) as AttackTechnique[];
    },
    staleTime: 60 * 60_000, // 1 hour — technique data is static
  });
}

// Techniques seen in threat_items over the last N days, with hit counts
export function useTechniqueHeatmap(days = 30) {
  return useQuery({
    queryKey: ["technique_heatmap", days],
    queryFn: async () => {
      const since = new Date(Date.now() - days * 86400000).toISOString();
      const { data, error } = await supabase
        .from("threat_items")
        .select("mitre_techniques, severity, published_at")
        .gte("published_at", since)
        .not("mitre_techniques", "eq", "{}");

      if (error) throw error;

      // Build technique_id → {count, severities} map
      const map = new Map<string, { count: number; critical: number; high: number }>();
      for (const item of data ?? []) {
        for (const tid of (item.mitre_techniques as string[]) ?? []) {
          if (!map.has(tid)) map.set(tid, { count: 0, critical: 0, high: 0 });
          const e = map.get(tid)!;
          e.count++;
          if (item.severity === "critical") e.critical++;
          if (item.severity === "high")     e.high++;
        }
      }

      return Array.from(map.entries())
        .map(([technique_id, stats]) => ({ technique_id, ...stats }))
        .sort((a, b) => b.count - a.count);
    },
    staleTime: 5 * 60_000,
  });
}
